// Populate the year dropdown from the data. Both Existing + Pipeline have
// year-built fields; we union all distinct years present in the current
// status mode and sort descending so newest is first.
function populatePropYearFilter() {
  const sel = document.getElementById('prop-year-filter');
  if (!sel) return;
  // The 'Proposed' mode pulls planned/proposed records (which carry the
  // underlying status 'Under Construction'); for the other two modes we filter
  // by status directly. Either way we want delivery years for the active scope.
  const matchingStatus = state.propStatus === 'all'
    ? RAW_DATA.map(applyUserEdits)
    : (state.propStatus === 'Proposed'
      ? RAW_DATA.map(applyUserEdits).filter(p => isPlannedProposed(p))
      : RAW_DATA.map(applyUserEdits).filter(p => p.status === state.propStatus && !isPlannedProposed(p)));
  const years = new Set();
  for (const p of matchingStatus) {
    if (p.yearBuilt) years.add(p.yearBuilt);
  }
  const sortedYears = [...years].sort((a, b) => b - a);
  const prevValue = sel.value;
  sel.innerHTML = '<option value="all">All Years</option>' +
    sortedYears.map(y => `<option value="${y}">${y}</option>`).join('');
  // Preserve selection if still valid; otherwise reset to All
  if (prevValue !== 'all' && sortedYears.includes(parseInt(prevValue, 10))) {
    sel.value = prevValue;
  } else {
    sel.value = 'all';
    state.propYear = 'all';
  }
}
populatePropYearFilter();
