// Pipeline CSV export — same pattern, scoped to Under Construction properties.
const pipelineExportBtn = document.getElementById('pipeline-export-btn');
if (pipelineExportBtn) {
  pipelineExportBtn.addEventListener('click', () => {
    const compSetIds = (state.compSetMode === 'viewing' && state.activeCompSetId && compSets[state.activeCompSetId])
      ? new Set(compSets[state.activeCompSetId].propertyIds) : null;
    const ucData = RAW_DATA.map(applyUserEdits).filter(p => {
      if (compSetIds) {
        if (!compSetIds.has(p.id)) return false;
      } else {
        if (!matchesClass(p)) return false;
        if (state.productTypes.size > 0 && !state.productTypes.has(p.style)) return false;
        if (state.cities.size > 0 && !state.cities.has(p.city)) return false;
        if (state.submarkets.size > 0 && !state.submarkets.has(p.submarket)) return false;
      }
      if (p.status !== 'Under Construction') return false;
      // Mirror the on-screen pipeline stage toggle so the export matches the view
      const stage = p.pipelineStage || 'UC';
      if (state.pipelineStageFilter === 'UC' && stage !== 'UC') return false;
      if (state.pipelineStageFilter === 'planned' && stage === 'UC') return false;
      return true;
    });
    ucData.sort((a, b) => {
      const ad = monthYearToDate(a.monthBuilt, a.yearBuilt);
      const bd = monthYearToDate(b.monthBuilt, b.yearBuilt);
      return (ad ? ad.getTime() : Infinity) - (bd ? bd.getTime() : Infinity);
    });
    const headers = [
      'Project', 'Address', 'City', 'Submarket', 'Product Type',
      'Developer', 'Owner', 'Units', 'Construction Begin', 'Est. Delivery',
      'Pre-Leasing %', 'Class', 'Year Built', 'Lat', 'Lng'
    ];
    const rows = ucData.map(p => [
      p.name, p.address, p.city, p.submarket, p.style,
      p.developer || '', p.owner || '',
      p.units, p.constructionBegin || '',
      fmt.monthYear(p.monthBuilt, p.yearBuilt),
      p.preLeasing == null ? '' : p.preLeasing.toFixed(1),
      p.class, p.yearBuilt, p.lat, p.lng
    ]);
    const stamp = new Date().toISOString().slice(0, 10);
    downloadCsv(`Willow_Bridge_Pipeline_${stamp}.csv`, headers, rows);
  });
}

// ============================================================================
// COMP SET BUILDER — wiring for the Property Index toolbar + sidebar list
// ============================================================================

// Toggle a property in the current comp set selection (used during 'building' mode)
function toggleCompSetSelection(pid) {
  if (state.compSetSelection.has(pid)) {
    state.compSetSelection.delete(pid);
  } else {
    state.compSetSelection.add(pid);
  }
  // Update just the affected row + the count chip — avoid a full re-render which
  // would scroll the table back to top and feel laggy on large sets.
  const tr = document.querySelector(`#table-properties tbody tr[data-pid="${pid}"]`);
  if (tr) {
    const isSelected = state.compSetSelection.has(pid);
    tr.classList.toggle('cs-selected', isSelected);
    const cb = tr.querySelector('input[type="checkbox"]');
    if (cb) cb.checked = isSelected;
  }
  updateCompSetUI();
}

// Refresh the count pill + button visibility based on current selection size
function updateCompSetUI() {
  const n = state.compSetSelection.size;
  const countEl = document.getElementById('cs-selection-count');
  const buildState = document.getElementById('cs-side-build-state');
  const saveBtn = document.getElementById('cs-save-btn');
  const toggleBtn = document.getElementById('cs-toggle-build');
  const picker = document.getElementById('cs-picker');
  const editBtn = document.getElementById('cs-side-edit');
  const exitBtn = document.getElementById('cs-side-exit');
  const statusEl = document.getElementById('cs-side-status');
  if (!toggleBtn) return;

  const building = state.compSetMode === 'building';
  const viewing = state.compSetMode === 'viewing' && state.activeCompSetId && compSets[state.activeCompSetId];

  if (buildState) buildState.style.display = building ? '' : 'none';
  if (countEl) countEl.textContent = `${n} selected`;
  if (saveBtn) saveBtn.disabled = n === 0;
  toggleBtn.style.display = building ? 'none' : '';
  if (picker) picker.style.display = building ? 'none' : '';
  if (editBtn) editBtn.style.display = (!building && viewing) ? '' : 'none';
  if (exitBtn) exitBtn.style.display = (!building && viewing) ? '' : 'none';

  if (statusEl) {
    if (viewing) {
      const cs = compSets[state.activeCompSetId];
      const units = compSetProperties(cs.id).reduce((s, p) => s + (p.units || 0), 0);
      statusEl.style.display = '';
      statusEl.innerHTML = `<strong>${cs.propertyIds.length}</strong> properties · <strong>${units.toLocaleString()}</strong> units<br>
        <span class="cs-side-scope">Scoping every view</span>`;
    } else {
      statusEl.style.display = 'none';
    }
  }
}

// Render the saved Comp Sets list — now as a dropdown picker in the Property
// Index toolbar rather than a sidebar list. The picker shows every saved set
// plus a special "— Comp Sets —" placeholder when nothing's active. There's
// also a "Delete current set" affordance when a set is active, surfaced via
// the active banner's existing controls (we extend the banner with a delete
// button so users don't lose the ability to remove sets).
function renderCompSetList() {
  const picker = document.getElementById('cs-picker');
  if (!picker) return;
  const sets = Object.values(compSets).sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  const placeholder = sets.length === 0 ? '— No Saved Sets —' : '— Activate Comp Set —';
  picker.innerHTML = `<option value="">${placeholder}</option>` +
    sets.map(s => { const dn = compSetDealName(s); return `<option value="${escapeHTML(s.id)}" ${state.activeCompSetId === s.id ? 'selected' : ''}>${escapeHTML(s.name)} · ${s.propertyIds.length}${dn ? ' · ↔ ' + escapeHTML(dn) : ''}</option>`; }).join('');
  // If active, select that option
  if (state.activeCompSetId) picker.value = state.activeCompSetId;
}

// Activate (or toggle off) a saved comp set
function activateCompSet(id) {
  if (!compSets[id]) return;
  // Clicking the already-active set deactivates it
  if (state.activeCompSetId === id) {
    exitCompSet();
    return;
  }
  state.activeCompSetId = id;
  state.compSetMode = 'viewing';
  // Clear ad-hoc filters so the comp set's scope is the only filter in play
  state.submarkets.clear();
  state.cities.clear();
  state.productTypes.clear();
  state.classes.clear();   // comp set scope rules; show all classes within it
  state.status = 'all';
  state.minUnitSF = 0;
  state.compSetSelection.clear();
  // Reset chip UIs
  document.querySelectorAll('#filter-status .chip').forEach(c => c.classList.toggle('active', c.dataset.value === 'all'));
  document.querySelectorAll('#filter-unitsize .chip').forEach(c => c.classList.toggle('active', c.dataset.value === '0'));
  document.querySelectorAll('#filter-product-type .product-chip').forEach(c => c.classList.remove('active'));
  document.querySelectorAll('#filter-class .chip').forEach(c => c.classList.toggle('active', c.dataset.value === 'all'));
  // Update banner
  updateCompSetBanner();
  renderCompSetList();
  renderSubmarketList();
  renderCityList();
  renderAll();
}

function exitCompSet() {
  state.activeCompSetId = null;
  state.compSetMode = 'off';
  updateCompSetBanner();
  renderCompSetList();
  renderSubmarketList();
  renderCityList();
  renderAll();
}

function updateCompSetBanner() {
  const banner = document.getElementById('comp-set-active-banner');
  const nameEl = document.getElementById('cs-banner-name');
  const metaEl = document.getElementById('cs-banner-meta');
  if (!banner) return;
  if (state.compSetMode === 'viewing' && state.activeCompSetId && compSets[state.activeCompSetId]) {
    const cs = compSets[state.activeCompSetId];
    banner.style.display = '';
    nameEl.textContent = cs.name;
    const dn = compSetDealName(cs);
    metaEl.textContent = `· ${cs.propertyIds.length} properties${dn ? ' · Tied to ' + dn : ''} · All filters scoped to this set`;
  } else {
    banner.style.display = 'none';
  }
}

// Build button — enter selection mode
const csToggleBuildBtn = document.getElementById('cs-toggle-build');
if (csToggleBuildBtn) {
  csToggleBuildBtn.addEventListener('click', () => {
    // If a comp set is currently active, exit it first so the user can pick
    // from the full property list rather than just the current set
    if (state.compSetMode === 'viewing') exitCompSet();
    state.compSetMode = 'building';
    state.compSetSelection.clear();
    updateCompSetUI();
    renderProperties();
  });
}

// Cancel button — exit building mode without saving
const csCancelBtn = document.getElementById('cs-cancel-btn');
if (csCancelBtn) {
  csCancelBtn.addEventListener('click', () => {
    state.compSetMode = 'off';
    state.compSetSelection.clear();
    updateCompSetUI();
    renderProperties();
  });
}

// Save button — prompt for name, persist, switch to viewing mode
const csSaveBtn = document.getElementById('cs-save-btn');
if (csSaveBtn) {
  csSaveBtn.addEventListener('click', () => {
    if (state.compSetSelection.size === 0) return;
    const name = prompt('Name this comp set:\n(e.g. "North Tempe Class A Lease-Up Set")');
    if (!name || !name.trim()) return;
    const trimmed = name.trim();
    const id = 'cs-' + Date.now();
    compSets[id] = {
      id,
      name: trimmed,
      propertyIds: [...state.compSetSelection],
      createdBy: syncState.editorName || 'Anonymous',
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    saveCompSets();
    pushCompSet(compSets[id]);
    // Switch to viewing mode for the just-saved set
    state.compSetMode = 'off';
    state.compSetSelection.clear();
    updateCompSetUI();
    activateCompSet(id);
  });
}

// New set straight on the map (search + click), optionally tied to a pipeline deal
const csNewMap = document.getElementById('cs-new-map');
if (csNewMap) csNewMap.addEventListener('click', () => openManageCompSet(null, { isNew: true }));

// Deep links from Pipeline: ?compset=<set id or uuid> opens that set; ?deal=<deal uuid> starts a set tied to that deal
(function compSetDeepLinks() {
  const q = new URLSearchParams(location.search);
  const csParam = q.get('compset'), dealParam = q.get('deal');
  if (!csParam && !dealParam) return;
  let tries = 0;
  const go = () => {
    const sets = Object.values(compSets);
    if (csParam) {
      const cs = sets.find(s => s.id === csParam || s.uuid === csParam);
      if (!cs && tries++ < 40) return setTimeout(go, 250);
      if (!cs) return;
      const tab = document.querySelector('.tab[data-view="properties"]'); if (tab) tab.click();
      if (state.activeCompSetId !== cs.id) activateCompSet(cs.id);
      return;
    }
    const opp = cmDealOpp(dealParam);
    if (!opp && tries++ < 40) return setTimeout(go, 250);
    if (!opp) return;
    const tab = document.querySelector('.tab[data-view="properties"]'); if (tab) tab.click();
    const existing = sets.find(s => s.dealId === dealParam);
    if (existing) { if (state.activeCompSetId !== existing.id) activateCompSet(existing.id); openManageCompSet(existing.id); }
    else openManageCompSet(null, { isNew: true, dealId: dealParam, name: (opp.name || 'Deal') + ' comp set' });
  };
  setTimeout(go, 300);
})();

// Edit the active comp set from the banner or the sidebar
const csBannerEdit = document.getElementById('cs-banner-edit');
if (csBannerEdit) csBannerEdit.addEventListener('click', openManageCompSet);
const csSideEdit = document.getElementById('cs-side-edit');
if (csSideEdit) csSideEdit.addEventListener('click', openManageCompSet);
const csSideExit = document.getElementById('cs-side-exit');
if (csSideExit) csSideExit.addEventListener('click', exitCompSet);

// Comp set editor modal — backdrop click closes
const cmModalEl = document.getElementById('cm-modal');
if (cmModalEl) {
  cmModalEl.addEventListener('click', e => { if (e.target === cmModalEl) closeManageCompSet(); });
}

// Exit comp set banner button
const csBannerClose = document.getElementById('cs-banner-close');
if (csBannerClose) {
  csBannerClose.addEventListener('click', exitCompSet);
}

// Delete the active comp set
const csBannerDelete = document.getElementById('cs-banner-delete');
if (csBannerDelete) {
  csBannerDelete.addEventListener('click', () => {
    if (!state.activeCompSetId) return;
    const cs = compSets[state.activeCompSetId];
    if (!cs) return;
    if (!confirm(`Delete comp set "${cs.name}"? This cannot be undone.`)) return;
    const idToDelete = state.activeCompSetId;
    delete compSets[idToDelete];
    saveCompSets();
    deleteCompSetCloud(idToDelete);
    exitCompSet();
  });
}

// Comp Set picker dropdown — activates the selected set on change
const csPicker = document.getElementById('cs-picker');
if (csPicker) {
  csPicker.addEventListener('change', e => {
    const id = e.target.value;
    if (!id) {
      // User picked the placeholder option — exit any active set
      if (state.activeCompSetId) exitCompSet();
      return;
    }
    activateCompSet(id);
  });
}

// Initial render of the picker + banner state
renderCompSetList();
updateCompSetBanner();
updateCompSetUI();

// ============================================================================
// WB DEALS + COMP SET INTELLIGENCE — wiring
// ============================================================================
const addDealBtn = document.getElementById('prop-add-deal-btn');
if (addDealBtn) addDealBtn.addEventListener('click', () => openWbDealModal(null));

const cpModalEl = document.getElementById('cp-modal');
if (cpModalEl) {
  cpModalEl.addEventListener('click', e => { if (e.target === cpModalEl) closeWbDealModal(); });
}
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  const m = document.getElementById('cp-modal');
  if (m && m.classList.contains('show')) { closeWbDealModal(); return; }
  const cm = document.getElementById('cm-modal');
  if (cm && cm.classList.contains('show')) closeManageCompSet();
});

// One-time offer to clear Phoenix-market records that came across with the
// shared storage key.
try { maybeOfferPhoenixPurge(); } catch (e) { console.error('[phx purge]', e); }

// Bring locally-stored WB deals into RAW_DATA before the first paint, then
// reconcile with the cloud in the background and repaint once truth lands.
syncCustomPropsIntoRawData();
(async () => {
  try { await reconcileCustomPropsOnBoot(); } catch (e) { console.error('[wbdeal boot]', e); }
  try { await pullCompFeesFromCloud(); } catch (e) { console.error('[compfees boot]', e); }
  try { subscribeCustomPropsRealtime(); subscribeCompFeesRealtime(); } catch (e) {}
  try { populatePropYearFilter(); renderAll(); } catch (e) {}
})();

// ============================================================================
// SYNC INDICATOR WIRING — must run after DOM is ready (topbar is in main HTML)
// ============================================================================
// Editor name button → now shows the signed-in Microsoft account; clicking
// it offers to sign out (identity itself is no longer user-editable — it
// comes from the Microsoft account used to sign in).
const editorNameBtn = document.getElementById('sync-editor-name');
if (editorNameBtn) {
  if (REQUIRE_MICROSOFT_SIGNIN) {
    editorNameBtn.title = 'Click to sign out';
    editorNameBtn.addEventListener('click', () => { signOut(); });
  } else {
    editorNameBtn.title = 'Click to change your name';
    editorNameBtn.addEventListener('click', () => {
      const current = syncState.editorName || '';
      const name = prompt('What\'s your name?\n(Tagged on every record you create or edit. Microsoft sign-in isn\'t enabled yet.)', current);
      if (name && name.trim()) saveEditorName(name.trim());
    });
  }
}

// Sync status pill → force a manual full reconcile (push local-newer data up,
// then pull server truth back down). Used by the user as a safety net if they
// want to be SURE everything they've edited has made it to the cloud.
const syncStatusBtn = document.getElementById('sync-status-btn');
if (syncStatusBtn) {
  syncStatusBtn.addEventListener('click', async () => {
    if (!syncState.enabled) {
      alert('Sync is disabled — Supabase client did not load. The dashboard is operating offline; edits are saved locally only.');
      return;
    }
    // Run all 4 boot reconciles in sequence — each pushes locally-newer
    // rows up before pulling server truth back down. This is the
    // belt-and-suspenders "make sure everything is in sync" action.
    syncState.status = 'syncing';
    updateSyncIndicator();
    try {
      await reconcilePropertyEditsOnBoot();
      await reconcileSaleCompsOnBoot();
      await reconcileCompSetsOnBoot();
      await reconcileOpportunitiesOnBoot();
      syncState.status = 'synced';
      syncState.lastSync = Date.now();
      updateSyncIndicator();
    } catch (e) {
      console.error('[manual sync] threw:', e);
      syncState.status = 'error';
      syncState.lastError = e && e.message ? e.message : String(e);
      updateSyncIndicator();
    }
  });
}

// Initial state — paint the indicator (auth gate is initialized where the
// Supabase client is set up, so it resolves as early as possible)
updateSyncIndicator();

// ============================================================================
// SIDEBAR FILTER ACCORDION — toggle open/closed; update summary line
// ============================================================================
// Each accordion shows a one-line summary of what's selected when collapsed,
// so the user can scan the sidebar without expanding everything.
function updateAccordionSummaries() {
  const ptEl = document.getElementById('product-type-summary');
  if (ptEl) {
    const sel = Array.from(state.productTypes);
    ptEl.textContent = sel.length === 0 ? 'All' : (sel.length === 1 ? sel[0] : `${sel[0]} +${sel.length - 1}`);
  }
  const cityEl = document.getElementById('city-summary');
  if (cityEl) {
    const sel = Array.from(state.cities);
    cityEl.textContent = sel.length === 0 ? 'All' : (sel.length === 1 ? sel[0] : `${sel[0]} +${sel.length - 1}`);
  }
  const smEl = document.getElementById('submarket-summary');
  if (smEl) {
    const sel = Array.from(state.submarkets);
    smEl.textContent = sel.length === 0 ? 'All' : (sel.length === 1 ? sel[0] : `${sel[0]} +${sel.length - 1}`);
  }
}
document.querySelectorAll('.accordion .acc-toggle').forEach(t => {
  t.addEventListener('click', () => {
    t.closest('.accordion').classList.toggle('collapsed');
  });
});
// Patch list renderers + chip clicks to update summaries automatically
const _origRenderCityList = renderCityList;
renderCityList = function() { _origRenderCityList.apply(this, arguments); updateAccordionSummaries(); };
const _origRenderSubmarketList = renderSubmarketList;
renderSubmarketList = function() { _origRenderSubmarketList.apply(this, arguments); updateAccordionSummaries(); };
// Product type chips don't go through a render function — patch the click
document.querySelectorAll('#filter-product-type .product-chip').forEach(c => {
  c.addEventListener('click', () => setTimeout(updateAccordionSummaries, 0));
});
updateAccordionSummaries();

renderAll();
